"""Human review layer shared by the CLI explorer and workbench export."""
STYLE = r'''
.mindmap{display:grid;grid-template-columns:110px minmax(0,1fr);gap:20px;align-items:start}.mind-root{background:#0d7377;color:white;padding:15px;border-radius:12px;margin-top:12px}.mind-branches{border-left:2px solid #b8d7d4;padding-left:18px}.mind-branch{position:relative;margin:12px 0;padding:10px 12px;background:#f5f9f9;border:1px solid #dfe8ec;border-radius:9px}.mind-branch:before{content:'';position:absolute;left:-20px;top:24px;width:19px;border-top:2px solid #b8d7d4}.mind-branch summary{cursor:pointer;font-weight:600}.mind-items{display:grid;gap:7px;max-height:280px;overflow:auto;margin-top:10px}.mind-items button{text-align:left;padding:8px 10px;font-size:13px;overflow-wrap:anywhere}.review-guide{padding:12px;background:#e9f3f0;border-radius:8px;margin:12px 0}.review-table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13px}.review-table td,.review-table th{padding:9px 7px;border-bottom:1px solid #dfe8ec;text-align:left;vertical-align:top;overflow-wrap:anywhere}.review-table th{background:#f4f8f8;font-weight:600}.review-fields th{width:29%}.review-raw{margin-top:16px}.review-raw summary{cursor:pointer;color:#57707f}.review-status{font-size:15px;font-weight:600;padding:12px;background:#fff3df;border-radius:8px}.review-status.matched{background:#e0f2e8}.review-scroll{overflow:auto;max-height:400px}.review-roles{display:flex;gap:8px;flex-wrap:wrap}.review-roles button[aria-pressed=true]{background:#0d7377;color:white}.review-flow{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}.review-flow span{background:#edf3f5;padding:5px 9px;border-radius:6px;font-size:12px}
@media(max-width:850px){.mindmap{grid-template-columns:1fr}.mind-root{margin:0}.mind-branches{margin-left:16px}.review-fields th{width:32%}}
@media print{button.gbtn,.bar,.review-roles{display:none}.layout{display:block}aside .panel{position:static;max-height:none}.panel{box-shadow:none;break-inside:avoid}.mind-items,.review-scroll{max-height:none;overflow:visible}}
'''

SCRIPT = r'''
let reviewRole='pm';
function reportSource(r){return ({demo:'合成演示',mock:'模拟验证',deidentified:'已声明脱敏数据',production:'已声明生产数据',live:'实际接口请求'})[r.provenance||r.evidence?.mode]||'来源未声明'}
function reviewStatus(r){const paired=Object.hasOwn(r,'expected')||Object.hasOwn(r,'expect_rows');return ({pass:paired?'与填写的预期一致':'报告检查通过（仅限声明范围）',fail:paired?'与填写的预期不一致':'报告检查未通过',computed_only:'已计算，尚未与独立预期核对',selected:'已选择语义，尚未执行',not_ready:'条件不足，尚未完成',error:'执行失败'})[r.status]||'查看报告状态与范围'}

const reviewPanel=element('section',undefined,'panel');reviewPanel.id='human-review';graphPanel.before(reviewPanel);
function reviewReportLabel(w){const r=w.report||{},bad=w.stale||(w.binding_errors||[]).length;const state=bad?'历史 / 未绑定':reviewStatus(r);return state+' · '+(r.metric_name||r.metric||w.name)+(Object.hasOwn(r,'metric_value')?' · 实际 '+humanValue(r.metric_value)+(r.metric_unit||''):'')}
const humanValue=v=>v===undefined?'未提供':v===null?'NULL（无值）':typeof v==='object'?JSON.stringify(v):String(v);
const fieldName=(ds,key)=>{const d=(m.datasets||[]).find(x=>x.name===ds),f=(d?.fields||[]).find(x=>x.name===key);return f?.cn?`${f.cn}（${key}）`:String(key)};
function tableInto(parent,headers,rows,cls=''){const t=element('table',undefined,'review-table '+cls);if(headers){const head=element('thead'),tr=element('tr');headers.forEach(h=>tr.append(element('th',h)));head.append(tr);t.append(head)}const b=element('tbody');for(const row of rows){const tr=element('tr');row.forEach((v,i)=>tr.append(element(!headers&&i===0?'th':'td',humanValue(v))));b.append(tr)}t.append(b);parent.append(t);return t}
function calculation(metric){const e=String(metric.expr||'').trim();if(/^count\s*\(\s*\*\s*\)$/i.test(e))return '记录行数：每条符合条件的输入计1次；其他字段为空也计入。';if(/^count\s*\(\s*distinct\s+(?:"[^"]+"|[A-Za-z_]\w*)\s*\)$/i.test(e))return '去重非空计数：所选字段重复值只计1次，NULL不计。';if(/^count\s*\(\s*(?:"[^"]+"|[A-Za-z_]\w*)\s*\)$/i.test(e))return '字段非空计数：所选字段非NULL的记录计入；重复值仍计入。';if(/^sum\s*\(\s*(?:"[^"]+"|[A-Za-z_]\w*)\s*\)$/i.test(e))return '按声明表达式求和；先核对范围，再核对各条记录的贡献。';if(/^avg\s*\(\s*(?:"[^"]+"|[A-Za-z_]\w*)\s*\)$/i.test(e))return '按声明表达式求平均；需核对NULL、分母与加权口径。';return '依照下列原表达式计算；复杂表达式需结合业务说明核对，视图不另造计算规则。'}
function scopeText(metric){const filters=(metric.filters||[]).map(f=>fieldName(metric.dataset,f.field)+' 属于 '+humanValue(f.values));if(metric.extra_where)filters.push('补充条件（原表达式）：'+metric.extra_where);return filters.length?filters.join('\n且 '):'未声明额外过滤；不代表已确认全部业务范围。'}
function showReport(parent,wrapper){const r=wrapper.report||wrapper,bad=Boolean(wrapper.stale||(wrapper.binding_errors||[]).length),mode=reportSource(r);
 let status=bad?'历史或未绑定证据：不能用于当前验收':reviewStatus(r);
 parent.append(element('div',status,'review-status '+(!bad&&r.status==='pass'?'matched':'')),element('p','数据/执行来源：'+mode+'。结果一致不代表业务负责人已接受。','muted'));
 if(bad)parent.append(element('p',(wrapper.binding_errors||[]).join('；')||'模型、数据或相关条件已变化，请重新核对。'));
 if(Object.hasOwn(r,'metric_value')){tableInto(parent,['核对项','独立预期','实际'],[['指标值',r.expected?.metric_value,r.metric_value],['单位','按业务定义确认',r.metric_unit||'未定义'],['符合条件的输入记录数',r.expected?.matched_row_count,r.matched_row_count]]);const box=element('div',undefined,'review-scroll');tableInto(box,(r.detail_columns||[]).map(c=>bad?c:fieldName(r.dataset,c)),r.detail_rows||[]);parent.append(element('h3','实际输入明细（当前页）'),box);if(r.expected?.detail_rows){const expected=element('details');expected.append(element('summary','查看独立预期明细'));tableInto(expected,r.detail_columns||[],r.expected.detail_rows);parent.append(expected)}parent.append(element('p','先核对包含/排除与重复、NULL反例。去重值不等于输入明细行数；分页不改变总指标。','muted'))}
 else if(r.error)parent.append(element('p',humanValue(r.error)));
 if(r.boundary)parent.append(element('p',r.boundary,'muted'));
}
function renderHumanDetails(title,obj){$('detailTitle').textContent=title;const target=$('detail');target.replaceChildren();
 if(obj.report||obj.metric_value!==undefined||obj.binding_errors){showReport(target,obj)}
 else if(obj.dataset&&obj.id){const ds=(m.datasets||[]).find(x=>x.name===obj.dataset);target.append(element('div',reviewRole==='pm'?'核对：算谁、包含/排除什么、重复和NULL怎么算、结果是否符合业务。':'核对：来源粒度→过滤→表达式→快照→明细→消费者；不要只看SQL能运行。','review-guide'));tableInto(target,null,[['业务名称',obj.name||obj.id],['业务说明',obj.caliber?.note||'尚未填写'],['来源',ds?.cn?`${ds.cn}（${obj.dataset}）`:obj.dataset],['一行代表什么',ds?.grain],['计算方法',calculation(obj)],['纳入范围',scopeText(obj)],['计算表达式',obj.expr],['单位',obj.unit],['时间含义',({current:'当前状态',event:'业务事件',snapshot:'定期快照'})[obj.time_requirement||ds?.temporal?.kind]||obj.time_requirement||ds?.temporal?.kind]],'review-fields');const flow=element('div',undefined,'review-flow');['来源记录','→ 按范围过滤','→ 计算指标 / 展示输入明细','→ 核对独立预期','→ 交给消费者'].forEach(x=>flow.append(element('span',x)));target.append(flow);
 const results=(data.reports||[]).filter(x=>x.report?.metric===obj.id);target.append(element('h3','此指标的验证记录'));if(!results.length)target.append(element('p','尚无关联报告；定义可读不等于数值已经验证。'));for(const r of results){const b=element('button',reviewReportLabel(r));b.onclick=()=>inspect('结果核对 · '+(obj.name||obj.id),r);target.append(b)}
 }else if(obj.source||obj.fields){tableInto(target,null,[['名称',obj.cn||obj.name],['实际来源声明',obj.source],['行粒度',obj.grain],['主键声明',obj.primary_key],['主体字段声明',obj.tenant_field],['业务对象',obj.ontology_ref],['回答边界',obj.ai?.instructions]],'review-fields');tableInto(target,['业务字段','来源字段','类型 / 角色'],(obj.fields||[]).map(f=>[f.cn||'待补',f.name,[f.type,f.role].filter(Boolean).join(' / ')]));target.append(element('p','主键和主体字段是声明；唯一性、真实权限与实际执行仍需各自证据。','muted'))
 }else if(obj.from&&obj.to){tableInto(target,null,[['关系方向',obj.from+' → '+obj.to],['业务含义',obj.predicate||obj.note],['关联键',humanValue(obj.from_columns||obj.join_key)+' → '+humanValue(obj.to_columns||obj.join_key)],['基数',obj.cardinality||'未声明'],['落地方式',obj.mapping||'数据表关系'],['可遍历',obj.traversable===undefined?'未声明':obj.traversable],['依据',obj.evidence]],'review-fields');target.append(element('p','核对1侧是否唯一、关联后是否重复累计；图上有线不等于查询已经正确。','muted'))
 }else if(obj.attributes){tableInto(target,null,[['业务对象',obj.cn||obj.name],['含义',obj.note],['从属对象',obj.is_a||'未声明'],['映射到数据集',obj.projected_by],['证据来源',({owner_confirmed:'责任人确认',user_provided:'用户提供',model_inferred:'模型推断',data_observed:'数据观测'})[obj.evidence?.source]||'未声明'],['依据与责任人',obj.evidence]],'review-fields');tableInto(target,['属性','标识','类型'],obj.attributes.map(f=>[f.cn||f.name,f.name,f.value_type||f.type||'未定义']))
 }else{const labels={question:'业务问题',profile:'使用方式',requirements:'本场景约定',datasets:'涉及数据集',metrics:'涉及指标',state:'处理状态',status:'处理状态',owner_role:'需要谁处理',role:'需要谁处理',text:'待解决问题',resolution:'处理结果',resolved_by:'处理人',basis:'依据',actor:'确认人',value:'已记录答案',property:'确认事项'};const rows=Object.entries(obj).filter(([k])=>labels[k]&&!['requirements','datasets','metrics'].includes(k)).map(([k,v])=>[labels[k],k==='profile'?({metric:'指标问数',nl2sql:'自由问数',action:'办理业务',policy:'政策适用',decision:'分析与决策'})[v]||v:v]);const requirementLabels={audience:'谁使用结果',time_scope:'时间范围与统计时点',acceptance:'预期与核对依据',access_boundary:'数据可见范围',refusal:'拒绝与异常',action_target:'办理对象',eligibility:'适用条件',permission:'权限条件',confirmation:'提交确认',idempotency:'重复执行',receipt:'结果回执',policy_source:'政策依据',effective_period:'有效时间',jurisdiction:'适用地域',exceptions:'例外',reviewer:'复核人',objective:'目标',alternatives:'备选方案',constraints:'约束',baseline:'比较基准',assumptions:'假设',evaluation:'评价方法'};for(const [k,v] of Object.entries(obj.requirements||{}))rows.push([requirementLabels[k]||k,v]);tableInto(target,null,rows.length?rows:[['说明',obj.note||'此对象暂无可读说明；请查看原始定义。']],'review-fields')}
 for(const [key,label] of [['datasets','涉及数据集'],['metrics','涉及指标']]){if(Array.isArray(obj[key])&&obj[key].length){target.append(element('h3',label));for(const id of obj[key]){const asset=(m[key]||[]).find(x=>(key==='datasets'?x.name:x.id)===id),b=element('button',asset?(asset.cn||asset.name||id)+'（'+id+'）':id+'（引用未找到）');if(asset)b.onclick=()=>inspect(label+' · '+(asset.cn||asset.name||id),asset);else b.disabled=true;target.append(b)}}}
 const raw=element('details',undefined,'review-raw');raw.open=reviewRole==='fde';raw.append(element('summary','原始定义与证据（供实现追溯）'),element('pre',JSON.stringify(obj,null,2)));target.append(raw);if(innerWidth<=850)$('detailTitle').scrollIntoView({block:'start'});
}
function renderReview(){reviewPanel.replaceChildren(element('h2','从这里开始人工核验'));const roles=element('div',undefined,'review-roles');for(const [key,label] of [['pm','业务 / 产品经理'],['fde','FDE / 实施工程师']]){const b=element('button',label);b.setAttribute('aria-pressed',String(reviewRole===key));b.onclick=()=>{reviewRole=key;renderReview();$('detailTitle').textContent='选择对象查看详情';$('detail').replaceChildren()};roles.append(b)}reviewPanel.append(roles,element('p',reviewRole==='pm'?'先从问题或指标进入，核对业务范围和正反例；再查看预期与实际结果，未定事项保留。':'先核对数据来源、粒度和字段映射，再看关系基数、执行证据与消费者状态。','review-guide'));
 const map=element('div',undefined,'mindmap'),root=element('div','本次交付\n问题 → 定义 → 证据','mind-root'),branches=element('div',undefined,'mind-branches');root.style.whiteSpace='pre-line';map.append(root,branches);reviewPanel.append(map);const q=$('search').value.toLowerCase();
 const groups=[['问题与使用范围',data.scenarios||[],x=>x.question||x.name||x.id],['对象与关系',[...(data.ontology?.entities||[]),...(data.ontology?.relations||[])],x=>x.from?x.from+' → '+x.to+' · '+(x.predicate||'待补含义'):x.cn||x.name],['指标与计算',m.metrics||[],x=>x.name||x.id],['数据与映射',m.datasets||[],x=>x.cn||x.name],['结果与证据',data.reports||[],reviewReportLabel],['待确认与问题',[...(data.gaps||[]),...(data.issues||[]),...(data.decisions||[])],x=>x.question||x.text||('确认：'+(x.property||x.gap_id||x.id||'业务决定'))]];
 for(const [name,items,label] of groups){const d=element('details',undefined,'mind-branch');d.open=q!==''||name===(reviewRole==='pm'?'指标与计算':'数据与映射');const shown=items.filter(x=>matches(x,q));d.append(element('summary',name+' · '+shown.length));const list=element('div',undefined,'mind-items');for(const obj of shown){const b=element('button',label(obj));b.onclick=()=>inspect(name+' · '+label(obj),obj);list.append(b)}if(!shown.length)list.append(element('span',q?'无匹配内容':'尚未登记；不能据此判断无需核对。','muted'));d.append(list);branches.append(d)}
 reviewPanel.append(element('p','此图用于导航与核对，不自动批准。图和字典均来自同一模型；仍需对照原始资料、独立反例和实际结果。','muted'));
}
$('search').addEventListener('input',renderReview);renderReview();
'''
